#include <iostream>

struct Traced {
    const char* name;
    explicit Traced(const char* n) : name(n) { std::cout << "  construct " << n << '\n'; }
    ~Traced() { std::cout << "  destroy " << name << '\n'; }
};

int main() {
    Traced outer("outer");
    {
        Traced inner("inner");
        Traced inner2("inner2");
    }                      // inner2 destroyed first, then inner
    std::cout << "scope ended\n";
}                          // outer destroyed last

#include <iostream>

int main() {
    int* p = new int(42);            // heap allocation, then construction
    std::cout << *p << '\n';
    delete p;                        // destruction, then release
    p = nullptr;                     // deleting nullptr is a safe no-op

    auto* prices = new double[3]{101.5, 102.25, 99.75};
    std::cout << prices[1] << '\n';  // 102.25
    delete[] prices;                 // array new must pair with delete[]
}

